ast [1].''"}, {"source": "remediation_change_log:100063", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_name ''1500 - 500 BC'' -> None"}, {"source": "remediation_change_log:100064", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s009: period_start ''-1000'' -> None"}, {"source": "remediation_change_log:151068", "url": "remediation_change_log", "quote": "served-image-2026-09-30-013: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Chapel_at_Posbury_-_geograph.org.uk_-_1736573.jpg/400px-Chapel_at_Posbury_-_geograph.org.uk_-_1736573.jpg'' -> ''/data/images/wiki/60212fa1/hero.webp''"}, {"source": "remediation_change_log:249183", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_name None -> ''1500 - 500 BC''"}, {"source": "remediation_change_log:249184", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s009: period_start None -> ''-800''"}, {"source": "remediation_change_log:385806", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s002: period_name ''1500 - 500 BC'' -> ''Undated''"}, {"source": "remediation_change_log:385807", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s002: period_start ''-800'' -> None"}]'::jsonb),
