ow mound [1].''"}, {"source": "remediation_change_log:102611", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_name ''4500 - 3000 BC'' -> None"}, {"source": "remediation_change_log:102612", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s012: period_start ''-4500'' -> None"}, {"source": "remediation_change_log:154545", "url": "remediation_change_log", "quote": "served-image-2026-09-30-018: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/3/3a/West_Lanyon_Quoit_-_geograph.org.uk_-_1964991.jpg'' -> ''/data/images/wiki/81be53ae/hero.webp''"}, {"source": "remediation_change_log:250213", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_name None -> ''4500 - 3000 BC''"}, {"source": "remediation_change_log:250214", "url": "remediation_change_log", "quote": "2026-10-04_fields-wd3-s011: period_start None -> ''-4000''"}, {"source": "remediation_change_log:325284", "url": "remediation_change_log", "quote": "import-hero-2026-10-06-005-002: thumbnail_url ''/data/images/wiki/81be53ae/hero.webp'' -> ''/data/images/wiki/81be53ae/West Lanyon Quoit - geograph.org.uk - 1964991.webp''"}, {"source": "remediation_change_log:386519", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s003: period_name ''4500 - 3000 BC'' -> ''Undated''"}, {"source": "remediation_change_log:386520", "url": "remediation_change_log", "quote": "2026-11-07_mechanical-period-fix-s003: period_start ''-4000'' -> None"}]'::jsonb),
